import {openAsBlob} from 'node:fs';
import {readFile,writeFile,mkdir,stat} from 'node:fs/promises';
import {join,extname,resolve,relative,isAbsolute} from 'node:path';
import {randomUUID,createHash} from 'node:crypto';
import {config,getKey,privateRoot} from './config.mjs';
const entries=new Map();
const heardKeys=new Set();
export const hasHeard=key=>heardKeys.has(key);
export function mediaKind(path){const extension=extname(path).slice(1).toLowerCase();if(['mp4','mkv','mov','avi','flv','webm','wmv','mpeg'].includes(extension))return {kind:'video',format:extension};if(['mp3','wav','m4a','aac','ogg','opus','flac','amr','aiff'].includes(extension))return {kind:'audio',format:extension};if(['png','jpg','jpeg','webp'].includes(extension))return {kind:'image',format:extension};throw Error('请选择音频、视频或图片文件。');}
export async function upload(path,signal){
 const c=config(),key=getKey(),root=join(privateRoot(),'uploads');await mkdir(root,{recursive:true});const cache=join(root,createHash('sha256').update(path+'\0'+key+'\0'+(await stat(path)).mtimeMs).digest('hex')+'.json');
 try{const old=JSON.parse(await readFile(cache,'utf8'));if(old.expires>Date.now())return old.url;}catch{}
 const target=new URL('/api/v1/uploads',new URL(c.baseURL).origin);target.searchParams.set('action','getPolicy');target.searchParams.set('model',c.model);const response=await fetch(target,{signal,headers:{Authorization:'Bearer '+key}});if(!response.ok)throw Error('音视频上传授权失败：HTTP '+response.status);const p=(await response.json()).data;if(!p?.upload_host||!p.upload_dir)throw Error('上传服务未返回有效授权。');
 const host=new URL(p.upload_host);if(host.protocol!=='https:'||!host.hostname.endsWith('.aliyuncs.com'))throw Error('上传域名异常。');const object=p.upload_dir+'/'+randomUUID()+extname(path),form=new FormData();for(const [name,value] of Object.entries({OSSAccessKeyId:p.oss_access_key_id,policy:p.policy,Signature:p.signature,'x-oss-object-acl':p.x_oss_object_acl||'private','x-oss-forbid-overwrite':'true',key:object,success_action_status:'200'}))form.set(name,value);form.set('file',await openAsBlob(path));
 const r=await fetch(host,{method:'POST',body:form,signal});if(!r.ok)throw Error('音视频上传失败：HTTP '+r.status);await r.arrayBuffer();const url='oss://'+object;await writeFile(cache,JSON.stringify({url,expires:Date.now()+47*3600000}));return url;
}
export async function mediaMarker(path,signal,songKey){const absolute=resolve(path),type=mediaKind(absolute);if(!(await stat(absolute)).isFile())throw Error('媒体文件不存在。');const url=await upload(absolute,signal),id=randomUUID();entries.set(id,{...type,url,used:false,songKey});return {marker:'QIAN_NATIVE_MEDIA:'+id,file:absolute,kind:type.kind,note:'原始媒体将在下一次主模型请求提供一次，不经过ASR或抽帧；需要重看时重新调用本工具。'};}
export function nativeParts(messages){const selected=new Map();for(const m of messages)for(const match of JSON.stringify(m).matchAll(/QIAN_NATIVE_MEDIA:([a-f0-9-]{36})/g)){const e=entries.get(match[1]);if(e&&!e.used)selected.set(match[1],e);}return {parts:[...selected.values()].map(e=>e.kind==='video'?{type:'video_url',video_url:{url:e.url}}:e.kind==='image'?{type:'image_url',image_url:{url:e.url}}:{type:'input_audio',input_audio:{data:e.url,format:e.format}}),commit(){for(const e of selected.values()){e.used=true;if(e.songKey)heardKeys.add(e.songKey);}}};}
export function wireMessages(options){const out=[];if(options.system)out.push({role:'system',content:options.system});for(const m of options.messages||[]){const blocks=typeof m.content==='string'?[{type:'text',text:m.content}]:m.content||[],text=blocks.filter(b=>b.type==='text').map(b=>b.text).join('\n');if(m.role==='tool'){out.push({role:'tool',tool_call_id:m.source?.callId,content:text||JSON.stringify(blocks)});continue;}if(m.role==='assistant'){const calls=blocks.filter(b=>b.type==='tool-call').map(b=>({id:b.id,type:'function',function:{name:b.name,arguments:b.arguments}}));out.push({role:'assistant',content:text||null,...(calls.length?{tool_calls:calls}:{})});continue;}out.push({role:m.role==='developer'?'system':m.role,content:text||JSON.stringify(blocks)});}return out;}
